window.AUTH=window.AUTH||{};window.AUTH["25-159"]={"d":"25-159","id":"2026/25-159","n":"Hoffmann v. WBI Energy Transmission, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioners Leonard W. Hoffmann, et al.","date":"2026-08-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/418892/20260813103936272_1%20-%20Brief%20for%20Petitioners.pdf","side":"pet","n":61},{"k":"respondent","label":"Brief of respondent WBI Energy Transmission, Inc.","date":"2026-09-14","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/424160/20260914155818845_25-159.Rsps%20Merits%20Br.pdf","side":"res","n":97},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2026-09-21","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/425110/20260921193036019_Hoffmann_bsacUnitedStates.pdf","side":"us","n":61},{"k":"reply","label":"Reply of petitioners Leonard W. Hoffmann, et al.","date":"2026-10-14","url":"https://www.supremecourt.gov/DocketPDF/25/25-159/429463/20261014120213063_1%20-%20Reply%20Brief%20for%20Petitioners.pdf","side":"pet","n":36}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Agency Holding Corp. v. Malley-Duff & Assocs., Inc.","cite":"483 U.S. 143","y":1987,"id":"1986/86-497","sc":1,"by":{"0":"26, 27, 28, 29","1":"41","2":"25, 26","3":"2"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"will apply except when a statutory purpose to the contrary is evident.","cite":"501 U.S. 104, 108"}]},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"by":{"0":"32"}},{"t":"case","label":"Brown v. United States","cite":"263 U.S. 78","y":1923,"id":"scdb/1923-012","sc":1,"by":{"0":"23, 24","1":"17","2":"27"}},{"t":"case","label":"Butner v. United States","cite":"440 U.S. 48","y":1979,"id":"1978/77-1410","sc":1,"by":{"0":"43","1":"38"}},{"t":"case","label":"Campbell v. City of Haverhill","cite":"155 U.S. 610","y":1895,"id":"scdb/1894-066","sc":1,"by":{"0":"24","3":"6"}},{"t":"case","label":"Cent. Neb. Pub. Power & Irrigation Dist. v. Fairchild","cite":"126 F.2d 302","y":1942,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/126/302/","by":{"0":"30","1":"18"}},{"t":"case","label":"Chattanooga Foundry & Pipe Works v. City of Atlanta","cite":"203 U.S. 390","y":1906,"id":"scdb/1906-040","sc":1,"by":{"0":"24"}},{"t":"case","label":"City of Bismarck v. Thom","cite":"261 N.W.2d 640","y":1977,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W.2d/261/640/","by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"make[s] certain that the landowner received the full ‘just compensation’ for his land, without diminution by attorney fees.","cite":"261 N.W.2d 640, 647"}]},{"t":"case","label":"Close Armstrong, LLC v. Trunkline Gas Co.","cite":"667 F. Supp. 3d 908","y":2023,"court":"N.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/667/908/","by":{"0":"40"}},{"t":"case","label":"Columbia Gas Transmission Corp. v. Exclusive Nat. Gas Storage Easement","cite":"962 F.2d 1192","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/962/1192/","by":{"0":"4"}},{"t":"case","label":"Columbia Gas Transmission, LLC v. Haas","cite":"341 F. Supp. 3d 607","y":2018,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/341/607/","by":{"0":"40"}},{"t":"case","label":"Dade County v. Brigham","cite":"47 So. 2d 602","y":1950,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/47/602/","by":{"0":"47"}},{"t":"case","label":"Davies Warehouse Co. v. Bowles","cite":"321 U.S. 144","y":1944,"id":"scdb/1943-055","sc":1,"by":{"0":"17","1":"38","2":"20","3":"3, 4"},"q":[{"src":"brief","b":0,"text":"[t]he great body of law in this country which controls . . . transfer of property[] and defines the rights of its owners . . . [was] found in the statutes and decisions of the state[s].","cite":"321 U.S. 144, 155"},{"src":"brief","b":0,"text":"the transfer of property . . . [and] the rights of its owners,","cite":"321 U.S. at 155"},{"src":"argument","who":"Chief Justice Roberts","text":"That's what Congress would have expected in 1947, which was just three years after this Court in Davies Warehouse reaffirmed its longstanding custom of looking to state law to give meaning and content to federal statutes."}]},{"t":"case","label":"Del. Riverkeeper Network v. Sec’y Pa. Dept. of Env’t Prot.","cite":"833 F.3d 360","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/833/360/","by":{"0":"39"}},{"t":"case","label":"Feltz v. Cent. Neb. Pub. Power & Irrigation Dist.","cite":"124 F.2d 578","y":1942,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/124/578/","by":{"0":"30, 31","1":"18"},"q":[{"src":"argument","who":"Mr. Hughes","text":"I -- I recognize the Feltz case of the Eighth Circuit out of 1942, and then another case decided by the same panel with the same dispute a couple weeks later in Fairchild has a single sentence that says Nebraska law applies."}]},{"t":"case","label":"Gas Transmission Nw., LLC v. FERC","cite":"157 F.4th 674","y":2025,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/157/674/","by":{"0":"41"}},{"t":"case","label":"Ga. Power Co. v. Sanders","cite":"617 F.2d 1112","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/617/1112/","by":{"0":"3, 35","1":"13","2":"30"}},{"t":"case","label":"Grand River Dam Auth. v. Thompson","cite":"118 F.2d 242","y":1941,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/118/242/","by":{"0":"30"}},{"t":"case","label":"Gulf Interstate Gas Co. v. Garvin","cite":"303 S.W.2d 260","y":1957,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/303/260/","by":{"0":"34","1":"25"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"look[ing] to the text in ‘context’ and in light of the statutory ‘purpose.’","cite":"588 U.S. 128, 141"}]},{"t":"case","label":"Kirby Forest Indus., Inc. v. United States","cite":"467 U.S. 1","y":1984,"id":"1983/82-1994","sc":1,"by":{"0":"14","1":"35, 36","2":"23"},"q":[{"src":"brief","b":0,"text":"[t]he practical effect of final judgment on the issue of just compensation is to give the [condemnor] an option to buy the property at the adjudicated price.","cite":"467 U.S. at 4"},{"src":"brief","b":1,"text":"an option to buy the property at the adjudicated price.","cite":"467 U.S. 1, 4"}]},{"t":"case","label":"Library of Congress v. Shaw","cite":"478 U.S. 310","y":1986,"id":"1985/85-54","sc":1,"by":{"0":"15, 16, 20"},"q":[{"src":"brief","b":0,"text":"in the absence of its consent, is immune from suit.","cite":"478 U.S. 310, 315"}]},{"t":"case","label":"Luber v. Milwaukee County","cite":"177 N.W.2d 380","y":1970,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/177/380/","by":{"0":"19"}},{"t":"case","label":"McCluny v. Silliman","cite":"3 Pet. 270","y":1830,"url":"https://www.courtlistener.com/c/Pet./3/270/","by":{"0":"24"}},{"t":"case","label":"McCulloch v. Maryland","cite":"4 Wheat. 316","y":1819,"url":"https://www.courtlistener.com/c/Wheat./4/316/","by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"the power to tax involves the power to destroy[.]","cite":"4 Wheat. 316, 431"}]},{"t":"case","label":"Miss. River Transmission Corp. v. Tabor","cite":"757 F.2d 662","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/757/662/","by":{"0":"3, 4"}},{"t":"case","label":"Monessen Sw. Ry. Co. v. Morgan","cite":"486 U.S. 330","y":1988,"id":"1987/86-1743","sc":1,"by":{"0":"35, 36","1":"37, 42","3":"4"},"q":[{"src":"brief","b":0,"text":"Congress’ failure to disturb a consistent judicial interpretation of a statute may provide some indication that ‘Congress at least acquiesces in, and apparently affirms, that [interpretation].’","cite":"486 U.S. 330, 338"}]},{"t":"case","label":"O’Melveny & Myers v. FDIC","cite":"512 U.S. 79","y":1994,"id":"1993/93-489","sc":1,"by":{"0":"43"}},{"t":"case","label":"O’Sullivan v. Felix","cite":"233 U.S. 318","y":1914,"id":"scdb/1913-159","sc":1,"by":{"0":"24, 25"}},{"t":"case","label":"Olson v. United States","cite":"292 U.S. 246","y":1934,"id":"scdb/1933-123","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"in as good a position pecuniarily as if his property had not been taken[.]","cite":"292 U.S. 246, 255"}]},{"t":"case","label":"PennEast Pipeline Co. v. New Jersey","cite":"594 U.S. 482","y":2021,"id":"2020/19-1039","sc":1,"by":{"0":"1, 11, 13, 31, 44, 45, 46","1":"1, 3, 4, 5, 8, 11, 26, 27, 28, 33, 34, 35, 36, 38, 40, 41, 43, 47","2":"2, 4, 5, 10, 15, 17-20, 23, 24, 29, 32","3":"14, 15, 22"},"q":[{"src":"brief","b":0,"text":"to regulate the transportation and sale of natural gas in interstate commerce.","cite":"594 U.S. 482, 489"},{"src":"brief","b":0,"text":"did not identify a mechanism for certificate holders to secure property rights necessary to build pipelines.","cite":"594 U.S. 482, 489"},{"src":"brief","b":1,"text":"For as long as the eminent domain power has been exercised by the United States, it has also been delegated to private parties.","cite":"594 U.S. at 495"},{"src":"brief","b":1,"text":"that certificate holders often had only an illusory right to build.","cite":"594 U.S. at 489"},{"src":"brief","b":2,"text":"As originally enacted, the NGA did not identify a mechanism for certificate holders to secure property rights necessary to build pipelines.","cite":"594 U.S. 482, 489"},{"src":"brief","b":2,"text":"The result was that certificate holders often had only an illusory right to build.","cite":"594 U.S. at 489"},{"src":"argument","who":"Justice Sotomayor","text":"And in PennEast, we said that the -- that the person who brings it brings with it the power of the federal government, all of it. MR. McNAMARA: Well, I don't think that's --"},{"src":"argument","who":"Justice Sotomayor","text":"We rejected the attempt in PennEast to divorce the eminent -- eminent domain power from the power to bring the compensation actions, and I don't see how your separation of these principles honors that."},{"src":"argument","who":"Justice Kavanaugh","text":"Well, if you put Miller together with Bodcaw and then PennEast, I think the three of those together are a problem for you. So why don't you address then the PennEast piece of that?"}]},{"t":"case","label":"Pinewood Manor, Inc. v. Vt. Agency of Transp.","cite":"668 A.2d 653","y":1995,"court":"Vt.","url":"https://www.courtlistener.com/c/A.2d/668/653/","by":{"0":"19"}},{"t":"case","label":"Puntenney v. Iowa Utils. Bd.","cite":"928 N.W.2d 829","y":2019,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/928/829/","by":{"0":"34"}},{"t":"case","label":"Reconstruction Fin. Corp. v. Beaver County","cite":"328 U.S. 204","y":1946,"id":"scdb/1945-071","sc":1,"by":{"0":"17, 25, 43","1":"38","2":"26"},"q":[{"src":"brief","b":0,"text":"[c]oncepts of real property [were] deeply rooted in state traditions, customs, habits, and laws.","cite":"328 U.S. 204, 210"},{"src":"brief","b":0,"text":"patently [ran] counter to the terms of the Act.","cite":"328 U.S. 204, 210"},{"src":"brief","b":1,"text":"application of settled state rules as to what constitutes ‘real property.’","cite":"328 U.S. at 210"}]},{"t":"case","label":"Rodriguez v. FDIC","cite":"589 U.S. 132","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/132/","sc":1,"by":{"0":"43"}},{"t":"case","label":"Sabal Trail Transmission, LLC v. 18.27 Acres of Land","cite":"59 F.4th 1158","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/59/1158/","by":{"0":"4","1":"13"}},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"by":{"0":"17","1":"38"},"q":[{"src":"brief","b":0,"text":"lies at the core of traditional state authority.","cite":"598 U.S. 651, 679"}]},{"t":"case","label":"Swango Homes, Inc. v. Columbia Gas Transmission Corp.","cite":"806 F. Supp. 180","y":1992,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./806/180/","by":{"0":"39"}},{"t":"case","label":"Tenn. Gas Pipeline Co. v. Permanent Easement for 7.053 Acres","cite":"931 F.3d 237","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/931/237/","by":{"0":"4","1":"13, 46","2":"16"}},{"t":"case","label":"Transcon. Gas Pipe Line Corp. v. Tieman","cite":"112 So. 2d 724","y":1959,"court":"La. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/112/724/","by":{"0":"34","1":"25"}},{"t":"case","label":"Transwestern Pipe Line Co. v. Yandell","cite":"367 P.2d 938","y":1961,"court":"N.M.","url":"https://www.courtlistener.com/c/P.2d/367/938/","by":{"0":"34","1":"25"}},{"t":"case","label":"Union Elec. Light & Power Co. v. Snyder Est. Co.","cite":"65 F.2d 297","y":1933,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/65/297/","by":{"0":"30"}},{"t":"case","label":"United States v. Beebe","cite":"127 U.S. 338","y":1888,"id":"scdb/1887-247","sc":1,"by":{"0":"28"}},{"t":"case","label":"United States v. Bodcaw Co.","cite":"440 U.S. 202","y":1979,"id":"1978/78-551","sc":1,"by":{"0":"47, 48","1":"9, 16, 17, 43","2":"2, 8, 12, 13, 19, 22","3":"8, 9, 13, 23"},"q":[{"src":"brief","b":1,"text":"indirect costs to the property owner caused by the taking of his land are generally not part of the just compensation to which he is constitutionally entitled.","cite":"440 U.S. at 203"},{"src":"brief","b":1,"text":"is a matter of legislative grace.","cite":"440 U.S. at 203"},{"src":"brief","b":2,"text":"generally not part of the just compensation to which he is constitutionally entitled.","cite":"440 U.S. 202, 203"},{"src":"brief","b":2,"text":"is a matter of legislative grace rather than constitutional command.","cite":"440 U.S. at 204"},{"src":"argument","who":"Justice Kavanaugh","text":"And in later eminent domain cases like Bodcaw, this Court has made clear that in eminent domain cases, compensation is grounded upon the Constitution because that's the only mechanism through which the United States can be forced to pay money."},{"src":"argument","who":"Justice Kavanaugh","text":"Well, if you put Miller together with Bodcaw and then PennEast, I think the three of those together are a problem for you. So why don't you address then the PennEast piece of that?"},{"src":"argument","who":"Ms. Jacoby","text":"The reason that Bodcaw and other cases have said that attorneys' fees are not included is based on an interpretation of the Fifth Amendment Just Compensation Clause to cover only, you know, compensation for the property and not the property owner."}]},{"t":"case","label":"United States v. Carmack","cite":"329 U.S. 230","y":1946,"id":"scdb/1946-016","sc":1,"by":{"0":"19, 20","1":"39, 40"},"q":[{"src":"brief","b":0,"text":"authorization . . . carries with it the sovereign’s full powers except such as are excluded expressly or by necessary implication.","cite":"329 U.S. 230, 243 n.13"},{"src":"brief","b":1,"text":"do not include sovereign powers greater than those expressed or necessarily implied.","cite":"329 U.S. 230, 243 n.13"},{"src":"argument","who":"Chief Justice Roberts","text":"Carmack, but it's a longstanding common-law principle that when Congress delegates the eminent domain power to an arm of the United States Government, that carries with it all of the United States' powers, but when it delegates it to a private party, that's necessarily a grant of limited powers."},{"src":"argument","who":"Justice Kavanaugh","text":"The case I would point to, decided in parallel with Miller, is Carmack, which says things are different when we have a private delegation of eminent domain."},{"src":"argument","who":"Justice Jackson","text":"Carmack in 1946, where this Court says things are different when Congress delegates eminent domain into private hands. That's a narrower delegation."}]},{"t":"case","label":"United States v. Great Falls Mfg. Co.","cite":"112 U.S. 645","y":1884,"id":"scdb/1884-073","sc":1,"by":{"0":"15","1":"3"},"q":[{"src":"brief","b":0,"text":"law will imply a promise to make the [compensation] required","cite":"112 U.S. 645, 656"}]},{"t":"case","label":"United States v. Kimbell Foods, Inc.","cite":"440 U.S. 715","y":1979,"id":"1978/77-1359","sc":1,"by":{"0":"3, 10, 37, 38, 40, 41, 42, 43","1":"8, 12, 45, 46, 47, 48, 49","2":"3, 7, 11, 32-34","3":"2, 13"},"q":[{"src":"brief","b":1,"text":"is filling the role of the condemner.","cite":"440 U.S. 715"},{"src":"brief","b":2,"text":"need for a nationally uniform body of law.","cite":"440 U.S. at 728"},{"src":"brief","b":2,"text":"disrupt commercial relationships predicated on state law.","cite":"440 U.S. at 729"},{"src":"argument","who":"Chief Justice Roberts","text":"North Dakota law controls unless Congress preempts it or the Kimbell Foods factors demand a uniform federal rule. We read this statute to do what Congress meant for it to do, ensure that pipeline companies had access to an eminent domain cause of action in all 50 states."},{"src":"argument","who":"Justice Barrett","text":"Just to clarify, your argument is that state law applies of its own force because it's a default unless Congress preempts it, as opposed to, in a federal common law/Kimbell Foods kind of way, you're not asking that federal courts adopt state rules as the rules of federal common law."},{"src":"argument","who":"Justice Jackson","text":"Do you think that Kimbell Foods has any relevance to this at all? Are we talking about a gap in the statute?"}]},{"t":"case","label":"United States v. Miller","cite":"317 U.S. 369","y":1943,"id":"scdb/1942-034","sc":1,"by":{"0":"24","1":"2, 9, 15, 17, 18, 19, 20, 21, 22, 36, 38, 41","2":"14-17, 21","3":"9, 17"},"q":[{"src":"brief","b":1,"text":"[T]he courts early adopted, and have retained, the concept of market value","cite":"317 U.S. 369, 374"},{"src":"brief","b":1,"text":"unless the legislature so provides, as it may.","cite":"317 U.S. at 376"},{"src":"brief","b":2,"text":"do not, and could not, affect questions of substantive right—such as the measure of compensation—grounded upon the Constitution of the United States.","cite":"317 U.S. at 379"}]},{"t":"case","label":"United States v. Nashville, Chattanooga & St. Louis Ry. Co.","cite":"118 U.S. 120","y":1886,"id":"scdb/1885-245","sc":1,"by":{"0":"28"}},{"t":"case","label":"United States v. New Mexico","cite":"455 U.S. 720","y":1982,"id":"1981/80-702","sc":1,"by":{"0":"21, 22","1":"40","3":"9"},"q":[{"src":"brief","b":0,"text":"so incorporated into the government structure as to [have] become instrumentalities of the United States[.]","cite":"455 U.S. at 736"},{"src":"argument","who":"Justice Sotomayor","text":"The New Mexico Supreme Court actually makes new law as a question of first impression in a Natural Gas Act condemnation because there wasn't a New Mexico case about how to value an easement."}]},{"t":"case","label":"United States v. Sargent","cite":"162 F. 81","y":1908,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./162/81/","by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"[i]t is better, when possible, to act in harmony rather than in conflict with the established policy of a state.","cite":"162 F. 81, 89"}]},{"t":"case","label":"WBI Energy Transmission, Inc. v. 189.9 rods, more or less","cite":"2021 WL 1234585","y":2021,"court":"D.N.D. Apr. 1","by":{"0":"4, 5, 18"}},{"t":"case","label":"Winooski Hydroelectric Co. v. Five Acres of Land","cite":"769 F.2d 79","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/769/79/","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 717f","url":"https://www.law.cornell.edu/uscode/text/15/717f","subs":["(h)","(c)","(d)","(e)"],"stext":{"head":"§717f. Construction, extension, or abandonment of facilities","paras":[[0,"(a) Extension or improvement of facilities on order of court; notice and hearing"],[0,"Whenever the Commission, after notice and opportunity for hearing, finds such action necessary or desirable in the public interest, it may by order direct a natural-gas company to extend or improve its transportation facilities, to establish physical connection of its transportation facilities with the facilities of, and sell natural gas to, any person or municipality engaged or legally authorized to engage in the local distribution of natural or artificial gas to the public, and for such purpose to extend its transportation facilities to communities immediately adjacent to such facilities or to territory served by such natural-gas company, if the Commission finds that no undue burden will be placed upon such natural-gas company thereby: Provided, That the Commission shall have no authority to compel the enlargement of transportation facilities for such purposes, or to compel such natural-gas company to establish physical connection or sell natural gas when to do so would impair its ability to render adequate service to its customers."],[0,"(b) Abandonment of facilities or services; approval of Commission"],[0,"No natural-gas company shall abandon all or any portion of its facilities subject to the jurisdiction of the Commission, or any service rendered by means of such facilities, without the permission and approval of the Commission first had and obtained, after due hearing, and a finding by the Commission that the available supply of natural gas is depleted to the extent that the continuance of service is unwarranted, or that the present or future public convenience or necessity permit such abandonment."],[0,"(c) Certificate of public convenience and necessity"],[0,"(1)(A) No natural-gas company or person which will be a natural-gas company upon completion of any proposed construction or extension shall engage in the transportation or sale of natural gas, subject to the jurisdiction of the Commission, or undertake the construction or extension of any facilities therefor, or acquire or operate any such facilities or extensions thereof, unless there is in force with respect to such natural-gas company a certificate of public convenience and necessity issued by the Commission authorizing such acts or operations: Provided, however, That if any such natural-gas company or predecessor in interest was bona fide engaged in transportation or sale of natural gas, subject to the jurisdiction of the Commission, on February 7, 1942, over the route or routes or within the area for which application is made and has so operated since that time, the Commission shall issue such certificate without requiring further proof that public convenience and necessity will be served by such operation, and without further proceedings, if application for such certificate is made to the Commission within ninety days after February 7, 1942. Pending the determination of any such application, the continuance of such operation shall be lawful."],[0,"(B) In all other cases the Commission shall set the matter for hearing and shall give such reasonable notice of the hearing thereon to all interested persons as in its judgment may be necessary under rules and regulations to be prescribed by the Commission; and the application shall be decided in accordance with the procedure provided in subsection (e) of this section and such certificate shall be issued or denied accordingly: Provided, however, That the Commission may issue a temporary certificate in cases of emergency, to assure maintenance of adequate service or to serve particular customers, without notice or hearing, pending the determination of an application for a certificate, and may by regulation exempt from the requirements of this section temporary acts or operations for which the issuance of a certificate will not be required in the public interest."],[0,"(2) The Commission may issue a certificate of public convenience and necessity to a natural-gas company for the transportation in interstate commerce of natural gas used by any person for one or more high-priority uses, as defined, by rule, by the Commission, in the case of—"],[1,"(A) natural gas sold by the producer to such person; and"],[1,"(B) natural gas produced by such person."],[0,"(d) Application for certificate of public convenience and necessity"],[0,"Application for certificates shall be made in writing to the Commission, be verified under oath, and shall be in such form, contain such information, and notice thereof shall be served upon such interested parties and in such manner as the Commission shall, by regulation, require."],[0,"(e) Granting of certificate of public convenience and necessity"],[0,"Except in the cases governed by the provisos contained in subsection (c)(1) of this section, a certificate shall be issued to any qualified applicant therefor, authorizing the whole or any part of the operation, sale, service, construction, extension, or acquisition covered by the application, if it is found that the applicant is able and willing properly to do the acts and to perform the service proposed and to conform to the provisions of this chapter and the requirements, rules, and regulations of the Commission thereunder, and that the proposed service, sale, operation, construction, extension, or acquisition, to the extent authorized by the certificate, is or will be required by the present or future public convenience and necessity; otherwise such application shall be denied. The Commission shall have the power to attach to the issuance of the certificate and to the exercise of the rights granted thereunder such reasonable terms and conditions as the public convenience and necessity may require."],[0,"(f) Determination of service area; jurisdiction of transportation to ultimate consumers"],[0,"(1) The Commission, after a hearing had upon its own motion or upon application, may determine the service area to which each authorization under this section is to be limited. Within such service area as determined by the Commission a natural-gas company may enlarge or extend its facilities for the purpose of supplying increased market demands in such service area without further authorization; and"],[0,"(2) If the Commission has determined a service area pursuant to this subsection, transportation to ultimate consumers in such service area by the holder of such service area determination, even if across State lines, shall be subject to the exclusive jurisdiction of the State commission in the State in which the gas is consumed. This section shall not apply to the transportation of natural gas to another natural gas company."],[0,"(g) Certificate of public convenience and necessity for service of area already being served"],[0,"Nothing contained in this section shall be construed as a limitation upon the power of the Commission to grant certificates of public convenience and necessity for service of an area already being served by another natural-gas company."],[0,"(h) Right of eminent domain for construction of pipelines, etc."],[0,"When any holder of a certificate of public convenience and necessity cannot acquire by contract, or is unable to agree with the owner of property to the compensation to be paid for, the necessary right-of-way to construct, operate, and maintain a pipe line or pipe lines for the transportation of natural gas, and the necessary land or other property, in addition to right-of-way, for the location of compressor stations, pressure apparatus, or other stations or equipment necessary to the proper operation of such pipe line or pipe lines, it may acquire the same by the exercise of the right of eminent domain in the district court of the United States for the district in which such property may be located, or in the State courts. The practice and procedure in any action or proceeding for that purpose in the district court of the United States shall conform as nearly as may be with the practice and procedure in similar action or proceeding in the courts of the State where the property is situated: Provided, That the United States district courts shall only have jurisdiction of cases when the amount claimed by the owner of the property to be condemned exceeds $3,000."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/717f?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1, 2, 3, 13, 14, 30, 39, 48","2":"4, 4, 4, 4, 2, 5, 6, 9-11, 16-21, 23-32","3":"2, 5, 7, 11, 13, 14, 15, 16, 17, 22"},"q":[{"src":"brief","b":0,"text":"exercise of the right of eminent domain in","cite":"15 U.S.C. § 717f(h)"},{"src":"brief","b":0,"text":"in the district court of the United States . . . or in the State courts.","cite":"15 U.S.C. § 717f(h)"},{"src":"brief","b":2,"text":"certificate of public convenience and necessity","cite":"15 U.S.C. 717f(c)"},{"src":"brief","b":2,"text":"shall conform as nearly as may be with the practice and procedure in similar action or proceeding in the courts of the State where the property is situated.","cite":"15 U.S.C. 717f(h)"}]},{"t":"usc","label":"16 U.S.C. § 814","url":"https://www.law.cornell.edu/uscode/text/16/814","stext":{"head":"§814. Exercise by licensee of power of eminent domain","paras":[[0,"When any licensee cannot acquire by contract or pledges an unimproved dam site or the right to use or damage the lands or property of others necessary to the construction, maintenance, or operation of any dam, reservoir, diversion structure, or the works appurtenant or accessory thereto, in conjunction with any improvement which in the judgment of the commission is desirable and justified in the public interest for the purpose of improving or developing a waterway or waterways for the use or benefit of interstate or foreign commerce, it may acquire the same by the exercise of the right of eminent domain in the district court of the United States for the district in which such land or other property may be located, or in the State courts. The practice and procedure in any action or proceeding for that purpose in the district court of the United States shall conform as nearly as may be with the practice and procedure in similar action or proceeding in the courts of the State where the property is situated: Provided, That United States district courts shall only have jurisdiction of cases when the amount claimed by the owner of the property to be condemned exceeds $3,000 1 Provided further, That no licensee may use the right of eminent domain under this section to acquire any lands or other property that, prior to October 24, 1992, were owned by a State or political subdivision thereof and were part of or included within any public park, recreation area or wildlife refuge established under State or local law. In the case of lands or other property that are owned by a State or political subdivision and are part of or included within a public park, recreation area or wildlife refuge established under State or local law on or after October 24, 1992, no licensee may use the right of eminent domain under this section to acquire such lands or property unless there has been a public hearing held in the affected community and a finding by the Commission, after due consideration of expressed public views and the recommendations of the State or political subdivision that owns the lands or property, that the license will not interfere or be inconsistent with the purposes for which such lands or property are owned."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/814?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 30","1":"5","2":"5, 6, 27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"40 U.S.C. § 3114","url":"https://www.law.cornell.edu/uscode/text/40/3114","stext":{"head":"§3114. Declaration of taking","paras":[[0,"(a) Filing and Content.—In any proceeding in any court of the United States outside of the District of Columbia brought by and in the name of the United States and under the authority of the Federal Government to acquire land, or an easement or right of way in land, for the public use, the petitioner may file, with the petition or at any time before judgment, a declaration of taking signed by the authority empowered by law to acquire the land described in the petition, declaring that the land is taken for the use of the Government. The declaration of taking shall contain or have annexed to it—"],[1,"(1) a statement of the authority under which, and the public use for which, the land is taken;"],[1,"(2) a description of the land taken that is sufficient to identify the land;"],[1,"(3) a statement of the estate or interest in the land taken for public use;"],[1,"(4) a plan showing the land taken; and"],[1,"(5) a statement of the amount of money estimated by the acquiring authority to be just compensation for the land taken."],[0,"(b) Vesting of Title.—On filing the declaration of taking and depositing in the court, to the use of the persons entitled to the compensation, the amount of the estimated compensation stated in the declaration—"],[1,"(1) title to the estate or interest specified in the declaration vests in the Government;"],[1,"(2) the land is condemned and taken for the use of the Government; and"],[1,"(3) the right to just compensation for the land vests in the persons entitled to the compensation."],[0,"(c) Compensation.—"],[1,"(1) Determination and award.—Compensation shall be determined and awarded in the proceeding and established by judgment. The judgment shall include interest, in accordance with section 3116 of this title, on the amount finally awarded as the value of the property as of the date of taking and shall be awarded from that date to the date of payment. Interest shall not be allowed on as much of the compensation as has been paid into the court. Amounts paid into the court shall not be charged with commissions or poundage."],[1,"(2) Order to pay.—On application of the parties in interest, the court may order that any part of the money deposited in the court be paid immediately for or on account of the compensation to be awarded in the proceeding."],[1,"(3) Deficiency judgment.—If the compensation finally awarded is more than the amount of money received by any person entitled to compensation, the court shall enter judgment against the Government for the amount of the deficiency."],[0,"(d) Authority of Court.—On the filing of a declaration of taking, the court—"],[1,"(1) may fix the time within which, and the terms on which, the parties in possession shall be required to surrender possession to the petitioner; and"],[1,"(2) may make just and equitable orders in respect of encumbrances, liens, rents, taxes, assessments, insurance, and other charges."],[0,"(e) Vesting Not Prevented or Delayed.—An appeal or a bond or undertaking given in a proceeding does not prevent or delay the vesting of title to land in the Government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/40/3114?type=usc&year=mostrecent&link-type=html"},"by":{"0":"14","1":"37"}},{"t":"usc","label":"42 U.S.C. § 4601","url":"https://www.law.cornell.edu/uscode/text/42/4601","stext":{"head":"§4601. Definitions","paras":[[0,"As used in this chapter—"],[0,"(1) The term \"Federal agency\" means any department, agency, or instrumentality in the executive branch of the Government, any wholly owned Government corporation, the Architect of the Capitol, the Federal Reserve banks and branches thereof, and any person who has the authority to acquire property by eminent domain under Federal law."],[0,"(2) The term \"State\" means any of the several States of the United States, the District of Columbia, the Commonwealth of Puerto Rico, any territory or possession of the United States, the Trust Territory of the Pacific Islands, and any political subdivision thereof."],[0,"(3) The term \"State agency\" means any department, agency, or instrumentality of a State or of a political subdivision of a State, any department, agency, or instrumentality of 2 or more States or of 2 or more political subdivisions of a State or States, and any person who has the authority to acquire property by eminent domain under State law."],[0,"(4) The term \"Federal financial assistance\" means a grant, loan, or contribution provided by the United States, except any Federal guarantee or insurance, any interest reduction payment to an individual in connection with the purchase and occupancy of a residence by that individual, and any annual payment or capital loan to the District of Columbia."],[0,"(5) The term \"person\" means any individual, partnership, corporation, or association."],[0,"(6)(A) The term \"displaced person\" means, except as provided in subparagraph (B)—"],[1,"(i) any person who moves from real property, or moves his personal property from real property—"],[2,"(I) as a direct result of a written notice of intent to acquire or the acquisition of such real property in whole or in part for a program or project undertaken by a Federal agency or with Federal financial assistance; or"],[2,"(II) on which such person is a residential tenant or conducts a small business, a farm operation, or a business defined in paragraph (7)(D), as a direct result of rehabilitation, demolition, or such other displacing activity as the lead agency may prescribe, under a program or project undertaken by a Federal agency or with Federal financial assistance in any case in which the head of the displacing agency determines that such displacement is permanent; and"],[1,"(ii) solely for the purposes of sections 4622(a) and (b) and 4625 of this title, any person who moves from real property, or moves his personal property from real property—"],[2,"(I) as a direct result of a written notice of intent to acquire or the acquisition of other real property, in whole or in part, on which such person conducts a business or farm operation, for a program or project undertaken by a Federal agency or with Federal financial assistance; or"],[2,"(II) as a direct result of rehabilitation, demolition, or such other displacing activity as the lead agency may prescribe, of other real property on which such person conducts a business or a farm operation, under a program or project undertaken by a Federal agency or with Federal financial assistance where the head of the displacing agency determines that such displacement is permanent."],[0,"(B) The term \"displaced person\" does not include—"],[1,"(i) a person who has been determined, according to criteria established by the head of the lead agency, to be either in unlawful occupancy of the displacement dwelling or to have occupied such dwelling for the purpose of obtaining assistance under this chapter;"],[1,"(ii) in any case in which the displacing agency acquires property for a program or project, any person (other than a person who was an occupant of such property at the time it was acquired) who occupies such property on a rental basis for a short term or a period subject to termination when the property is needed for the program or project."],[0,"(7) The term \"business\" means any lawful activity, excepting a farm operation, conducted primarily—"],[1,"(A) for the purchase, sale, lease and rental of personal and real property, and for the manufacture, processing, or marketing of products, commodities, or any other personal property;"],[1,"(B) for the sale of services to the public;"],[1,"(C) by a nonprofit organization; or"],[1,"(D) solely for the purposes of section 4622 of this title, for assisting in the purchase, sale, resale, manufacture, processing, or marketing of products, commodities, personal property, or services by the erection and maintenance of an outdoor advertising display or displays, whether or not such display or displays are located on the premises on which any of the above activities are conducted."],[0,"(8) The term \"farm operation\" means any activity conducted solely or primarily for the production of one or more agricultural products or commodities, including timber, for sale or home use, and customarily producing such products or commodities in sufficient quantity to be capable of contributing materially to the operator's support."],[0,"(9) The term \"mortgage\" means such classes of liens as are commonly given to secure advances on, or the unpaid purchase price of, real property, under the laws of the State in which the real property is located, together with the credit instruments, if any, secured thereby."],[0,"(10) The term \"comparable replacement dwelling\" means any dwelling that is (A) decent, safe, and sanitary; (B) adequate in size to accommodate the occupants; (C) within the financial means of the displaced person; (D) functionally equivalent; (E) in an area not subject to unreasonable adverse environmental conditions; and (F) in a location generally not less desirable than the location of the displaced person's dwelling with respect to public utilities, facilities, services, and the displaced person's place of employment."],[0,"(11) The term \"displacing agency\" means any Federal agency carrying out a program or project, and any State, State agency, or person carrying out a program or project with Federal financial assistance, which causes a person to be a displaced person."],[0,"(12) The term \"lead agency\" means the Department of Transportation."],[0,"(13) The term \"appraisal\" means a written statement independently and impartially prepared by a qualified appraiser setting forth an opinion of defined value of an adequately described property as of a specific date, supported by the presentation and analysis of relevant market information."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4601?type=usc&year=mostrecent&link-type=html"},"by":{"0":"36","2":"13"}},{"t":"usc","label":"16 U.S.C. § 824p","url":"https://www.law.cornell.edu/uscode/text/16/824p","subs":["(f)"],"by":{"0":"35, 36","2":"31, 30, 30"}},{"t":"rule","label":"Fed. R. Civ. P. 71.1","url":"https://www.law.cornell.edu/rules/frcp/rule_71.1","by":{"0":"3"}},{"t":"case","label":"Almota Farmers Elevator & Warehouse Co. v. United States","cite":"409 U.S. 470","y":1973,"id":"1972/71-951","sc":1,"by":{"1":"42"}},{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"by":{"1":"24"}},{"t":"case","label":"Baker Botts LLP v. ASARCO LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"will not deviate from the American Rule absent explicit statutory authority.","cite":"576 U.S. 121, 126"}]},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"by":{"1":"18"}},{"t":"case","label":"Berman v. Parker","cite":"348 U.S. 26","y":1954,"id":"1940-1955/348us26","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"the object is within the authority of Congress, the right to realize it through the exercise of eminent domain is clear.","cite":"348 U.S. 26, 33"}]},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"bound to enforce only the language that Congress and the President enacted.","cite":"559 U.S. 196, 211 n.13"}]},{"t":"case","label":"Board of Comm’rs of Jackson Cnty. v. United States","cite":"308 U.S. 343","y":1939,"id":"scdb/1939-014","sc":1,"by":{"1":"18","2":"27","3":"2, 14"},"q":[{"src":"brief","b":2,"text":"because recognition of state interests was not deemed inconsistent with federal policy.","cite":"308 U.S. 343, 352"}]},{"t":"case","label":"Campbell v. United States","cite":"138 Fed. Cl. 65","y":2018,"url":"https://www.courtlistener.com/c/Fed.%20Cl./138/65/","by":{"1":"30"}},{"t":"case","label":"Campbell v. United States","cite":"266 U.S. 368","y":1924,"id":"scdb/1924-020","sc":1,"by":{"1":"16, 31"},"q":[{"src":"brief","b":1,"text":"in as good a position pecuniarily as he would have been if his property had not been taken.","cite":"266 U.S. at 371"},{"src":"brief","b":1,"text":"not entitled to have more than that.","cite":"266 U.S. at 371"}]},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"by":{"1":"42"}},{"t":"case","label":"Cherokee Nation v. Southern Kan. Ry.","cite":"135 U.S. 641","y":1890,"id":"scdb/1889-250","sc":1,"by":{"1":"3, 20, 27, 37, 39","3":"11"},"q":[{"src":"brief","b":1,"text":"sufficient to secure the compensation to which, under the constitution, [the landowner] is entitled.","cite":"135 U.S. at 659"}]},{"t":"case","label":"Chesapeake & Ohio Ry. v. Kelly","cite":"241 U.S. 485","y":1916,"id":"scdb/1915-176","sc":1,"by":{"1":"42","3":"5"},"q":[{"src":"brief","b":1,"text":"inseparably connected with the right of action.","cite":"241 U.S. 485, 491"}]},{"t":"case","label":"City of Milwaukee v. Illinois & Michigan","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"the Court is compelled to consider federal questions which cannot be answered from federal statutes alone.","cite":"451 U.S. 304, 314"}]},{"t":"case","label":"Comparet v. United States","cite":"164 F.2d 452","y":1947,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/164/452/","by":{"1":"20"}},{"t":"case","label":"County of Maui v. Hawaii Wildlife Fund","cite":"590 U.S. 165","y":2020,"id":"2019/18-260","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"advance[s], in a manner consistent with the statute’s language, the statutory purposes that Congress sought to achieve.","cite":"590 U.S. 165, 184"}]},{"t":"case","label":"Danforth v. United States","cite":"308 U.S. 271","y":1939,"id":"scdb/1939-027","sc":1,"by":{"1":"17"}},{"t":"case","label":"DelCostello v. Int’l Bhd. of Teamsters","cite":"462 U.S. 151","y":1983,"id":"1982/81-2386","sc":1,"by":{"1":"43","2":"25"},"q":[{"src":"brief","b":1,"text":"[s]ince Erie, no decision of this Court has held or suggested that the Act requires borrowing state law to fill gaps in federal substantive statutes.","cite":"462 U.S. 151, 160 n.13"}]},{"t":"case","label":"Dohany v. Rogers","cite":"281 U.S. 362","y":1930,"id":"scdb/1929-051","sc":1,"by":{"1":"16","2":"12"},"q":[{"src":"brief","b":1,"text":"[a]ttorneys’ fees and expenses are not embraced within just compensation for land taken by eminent domain.","cite":"281 U.S. 362, 368"}]},{"t":"case","label":"Dooley v. Korean Air Lines","cite":"524 U.S. 116","y":1998,"id":"1997/97-704","sc":1,"by":{"1":"42","3":"4, 5"}},{"t":"case","label":"F.D. Rich Co. v. Industrial Lumber Co.","cite":"417 U.S. 116","y":1974,"id":"1973/72-1382","sc":1,"by":{"1":"41","3":"5"}},{"t":"case","label":"Hardt v. Reliance Standard Life Ins.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"unless a statute or contract provides otherwise.","cite":"560 U.S. 242, 252-253"}]},{"t":"case","label":"Hippely v. United States","cite":"173 Fed. Cl. 389","y":2024,"url":"https://www.courtlistener.com/c/Fed.%20Cl./173/389/","by":{"1":"30"}},{"t":"case","label":"John Hancock Mut. Life Ins. v. Casey","cite":"147 F.2d 762","y":1945,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/147/762/","by":{"1":"20"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs., Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"by":{"1":"49"}},{"t":"case","label":"Kimble v. Marvel Ent., LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"by":{"1":"2, 31"},"q":[{"src":"brief","b":1,"text":"lies first and foremost with Congress.","cite":"576 U.S. at 463"}]},{"t":"case","label":"Kohl v. United States","cite":"91 U.S. 367","y":1875,"id":"scdb/1875-135","sc":1,"by":{"1":"3, 14, 35, 41","2":"9, 14, 15, 25"},"q":[{"src":"brief","b":1,"text":"can neither be enlarged nor diminished by a State[,] [n]or can any State prescribe the manner in which it must be exercised.","cite":"91 U.S. at 373"},{"src":"brief","b":1,"text":"[w]hy speak of condemnation at all, if Congress had not in view an exercise of the right of eminent domain, and did not intend to confer * * * the right to invoke it?","cite":"91 U.S. at 375"},{"src":"brief","b":2,"text":"[n]or can any State prescribe the manner in which it must be exercised.","cite":"91 U.S. 367, 374"},{"src":"argument","who":"Mr. Hughes","text":"This Court said that clearly in Kohl and in 93.97 Acres. It's just the same that states don't get to regulate the federal government's power of war."},{"src":"argument","who":"Mr. Hughes","text":"The federal government's power, as this Court said in Kohl and in 93.97 Acres, is not subject to state regulation. So it is simply not a -- a sovereign immunity issue."},{"src":"argument","who":"Chief Justice Roberts","text":"It does not speak about just compensation because just compensation, even in the cases my friend cites, even in Kohl, where the Court says states can't interfere with the exercise of the federal eminent domain power, it goes on to say in Kohl: And this statute says nothing about the measure of just compensation."}]},{"t":"case","label":"L. Vogelstein & Co. v. United States","cite":"262 U.S. 337","y":1923,"id":"scdb/1922-195","sc":1,"by":{"1":"16"}},{"t":"case","label":"Luxton v. North River Bridge Co.","cite":"153 U.S. 525","y":1894,"id":"scdb/1893-251","sc":1,"by":{"1":"4","2":"15"},"q":[{"src":"brief","b":1,"text":"may, at its discretion, use its sovereign powers, directly or through a corporation * * * for the accommodation of interstate commerce.","cite":"153 U.S. 525, 530"}]},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"590 U.S. 296","y":2020,"id":"2019/18-1023","sc":1,"by":{"1":"23"}},{"t":"case","label":"Memphis Cmty. Sch. Dist. v. Stachura","cite":"477 U.S. 299","y":1986,"id":"1985/85-410","sc":1,"by":{"1":"42"}},{"t":"case","label":"Mississippi & Rum River Boom Co. v. Patterson","cite":"98 U.S. 403","y":1878,"id":"scdb/1878-111","sc":1,"by":{"1":"3, 14","2":"15"},"q":[{"src":"brief","b":1,"text":"to take private property for public uses.","cite":"98 U.S. at 406"}]},{"t":"case","label":"Mitchell v. United States","cite":"267 U.S. 341","y":1925,"id":"scdb/1924-103","sc":1,"by":{"1":"16"}},{"t":"case","label":"Mobil Oil Corp. v. Higginbotham","cite":"436 U.S. 618","y":1978,"id":"1977/76-1726","sc":1,"by":{"1":"46"}},{"t":"case","label":"Monongahela Nav. Co. v. United States","cite":"148 U.S. 312","y":1893,"id":"scdb/1892-151","sc":1,"by":{"1":"15, 31","2":"12"},"q":[{"src":"brief","b":1,"text":"compensation must be a full and perfect equivalent for the property taken,","cite":"148 U.S. 312, 326"},{"src":"brief","b":1,"text":"is for the property, and not to the owner.","cite":"148 U.S. at 326"},{"src":"brief","b":2,"text":"is for the property, and not to the owner.","cite":"148 U.S. 312, 326"},{"src":"argument","who":"Justice Sotomayor","text":"How do I deal with a 1893 case, Monongahela versus the United States, in which we said, \"It seems to have been a settled principle of universal law that the right to compensation is an incident to the exercise of eminent domain and that the one is so inseparably connected with the other that they may be said to exist not as a separate and distinct principle but as parts of one and the same principle\"?"}]},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"1":"13, 14"},"q":[{"src":"brief","b":1,"text":"Congress borrows terms of art in which are accumulated the legal tradition and meaning of centuries of practice, it presumably knows and adopts the cluster of ideas that were attached to each borrowed word in the body of learning from which it was taken.","cite":"342 U.S. 246, 263"}]},{"t":"case","label":"NAACP v. Federal Power Comm’n","cite":"425 U.S. 662","y":1976,"id":"1975/74-1608","sc":1,"by":{"1":"32, 48"},"q":[{"src":"brief","b":1,"text":"encourag[ing] the orderly development of plentiful supplies of * * * natural gas at reasonable prices.","cite":"425 U.S. 662, 670"}]},{"t":"case","label":"Nebraska v. United States","cite":"164 F.2d 866","y":1947,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/164/866/","by":{"1":"20"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"by":{"1":"34"}},{"t":"case","label":"Northwest Airlines, Inc. v. Transport Workers Union of Am.","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"by":{"1":"12, 46"},"q":[{"src":"brief","b":1,"text":"authority to construe a statute is fundamentally different from the authority to fashion a new rule.","cite":"451 U.S. 77, 97"},{"src":"brief","b":1,"text":"the authority to construe a statute is fundamentally different from the authority to fashion a new rule or to provide a new remedy which Congress has decided not to adopt.","cite":"451 U.S. 77, 97"}]},{"t":"case","label":"Pension Ben. Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"‘[S]everal equally tenable inferences’ may be drawn from such inaction, ‘including the inference that the existing legislation already incorporated the offered change.’","cite":"496 U.S. 633, 650"}]},{"t":"case","label":"Peter v. NantKwest, Inc.","cite":"589 U.S. 23","y":2019,"id":"2019/18-801","sc":1,"by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"mere failure to foreclose a fee award","cite":"589 U.S. 23, 30-31"}]},{"t":"case","label":"Rodriguez v. Federal Deposit Ins. Corp.","cite":"589 U.S. 132","y":2020,"id":"2019/18-1269","sc":1,"by":{"1":"46"}},{"t":"case","label":"Ruckelshaus v. Sierra Club","cite":"463 U.S. 680","y":1983,"id":"1982/82-242","sc":1,"by":{"1":"44"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1984,"id":"1983/82-472","sc":1,"by":{"1":"25","3":"17, 18"},"q":[{"src":"brief","b":3,"text":"Language in one statute usually sheds little light upon the meaning of different language in another statute, even when the two are enacted at or about the same time.","cite":"464 U.S. 16, 24–25"}]},{"t":"case","label":"Sabal Trail Transmission, LLC v. 3.921 Acres of Land","cite":"74 F.4th 1346","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/74/1346/","by":{"1":"13, 27","2":"16, 32"},"q":[{"src":"brief","b":1,"text":"the choice of how to exercise the eminent domain power and what additional compensation to provide belongs to Congress alone.","cite":"74 F.4th at 1350"},{"src":"brief","b":2,"text":"improperly expand[ ] federal common law.","cite":"74 F.4th at 1349"}]},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"by":{"1":"22"}},{"t":"case","label":"Schneidewind v. ANR Pipeline Co.","cite":"485 U.S. 293","y":1988,"id":"1987/86-986","sc":1,"by":{"1":"4","2":"32"},"q":[{"src":"brief","b":2,"text":"matters relating to wholesale sales and transportation of natural gas in interstate commerce.","cite":"485 U.S. 293, 305, 310"}]},{"t":"case","label":"Simpson v. Shepard (Minnesota Rate Cases)","cite":"230 U.S. 352","y":1913,"id":"scdb/1912-290","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"be[ing] compelled to pay more than [a property’s] fair market value.","cite":"230 U.S. 352, 451"}]},{"t":"case","label":"United States ex rel. Tennessee Valley Auth. v. Powelson","cite":"319 U.S. 266","y":1943,"id":"scdb/1942-061","sc":1,"by":{"1":"16, 17, 19","2":"21"},"q":[{"src":"brief","b":1,"text":"[t]here are numerous * * * losses which result from condemnation of properties but which are not compensable under the Fifth Amendment.","cite":"319 U.S. 266, 281"}]},{"t":"case","label":"Transwestern Pipeline Co. v. 17.19 Acres of Prop.","cite":"627 F.3d 1268","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/627/1268/","by":{"1":"23, 44","3":"20, 21"}},{"t":"case","label":"United States v. 13,255.53 Acres of Land","cite":"158 F.2d 874","y":1946,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/158/874/","by":{"1":"20"}},{"t":"case","label":"United States v. 19.86 Acres of Land","cite":"141 F.2d 344","y":1944,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/141/344/","by":{"1":"20"}},{"t":"case","label":"United States v. 564.54 Acres of Land","cite":"441 U.S. 506","y":1979,"id":"1978/78-488","sc":1,"by":{"1":"15, 17, 31, 32"},"q":[{"src":"brief","b":1,"text":"has been chosen to strike a fair ‘balance between the public’s need and the claimant’s loss’ upon condemnation of property for a public purpose.","cite":"441 U.S. 506, 512"},{"src":"brief","b":1,"text":"the dominant consideration always remains the same: What compensation is ‘just’ both to an owner whose property is taken and to the public that must pay the bill?","cite":"441 U.S. at 512"}]},{"t":"case","label":"United States v. 93.970 Acres of Land","cite":"360 U.S. 328","y":1959,"id":"1958/573","sc":1,"by":{"1":"22, 39, 41, 43","2":"14, 15, 18","3":"9, 10"},"q":[{"src":"brief","b":1,"text":"where essential interests of the Federal Government are concerned, federal law rules unless Congress chooses to make state laws applicable.","cite":"360 U.S. at 332"},{"src":"brief","b":1,"text":"essential interests of the Federal Government are concerned, federal law rules unless Congress chooses to make state laws applicable.","cite":"360 U.S. at 332"},{"src":"brief","b":2,"text":"chooses to make state laws applicable.","cite":"360 U.S. at 333"}]},{"t":"case","label":"United States v. Certain Parcels of Land in Philadelphia","cite":"145 F.2d 374","y":1944,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/145/374/","by":{"1":"20"}},{"t":"case","label":"United States v. Chandler-Dunbar Water Power Co.","cite":"229 U.S. 53","y":1913,"id":"scdb/1912-214","sc":1,"by":{"1":"20, 21"}},{"t":"case","label":"United States v. Cors","cite":"337 U.S. 325","y":1949,"id":"scdb/1948-092","sc":1,"by":{"1":"31"}},{"t":"case","label":"United States v. Dow","cite":"357 U.S. 17","y":1958,"id":"1957/102","sc":1,"by":{"1":"35"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"by":{"1":"45"}},{"t":"case","label":"United States v. Jones","cite":"109 U.S. 513","y":1883,"id":"scdb/1883-070","sc":1,"by":{"1":"3, 13, 15","3":"7, 8, 22"},"q":[{"src":"brief","b":1,"text":"limitation upon the use of the [eminent domain] power.","cite":"109 U.S. at 518"}]},{"t":"case","label":"United States v. Jotham Bixby Co.","cite":"55 F.2d 317","y":1932,"court":"S.D. Cal.","url":"https://www.courtlistener.com/c/F.2d/55/317/","by":{"1":"40"}},{"t":"case","label":"United States v. New River Collieries Co.","cite":"262 U.S. 341","y":1923,"id":"scdb/1922-196","sc":1,"by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"[m]ore would be unjust to the United States, and less would deny the owner what he is entitled to.","cite":"262 U.S. 341, 344"}]},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"by":{"1":"41"}},{"t":"case","label":"Ysleta Del Sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"by":{"1":"18"}},{"t":"usc","label":"15 U.S.C. § 717a","url":"https://www.law.cornell.edu/uscode/text/15/717a","by":{"1":"6"}},{"t":"usc","label":"25 U.S.C. § 640d-14","url":"https://www.law.cornell.edu/uscode/text/25/640d-14","subs":["(b)(2)"],"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"equal[ed] the reasonable cost of a decent, safe, and sanitary replacement dwelling.","cite":"25 U.S.C. § 640d-14(b)(2)"}]},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(a)(1)","(d)(1)(A)","(d)(2)(H)"],"by":{"1":"23","2":"13, 13"}},{"t":"usc","label":"33 U.S.C. § 532","url":"https://www.law.cornell.edu/uscode/text/33/532","stext":{"head":"§532. Eminent domain","paras":[[0,"There are conferred upon any individual, his heirs, legal representatives, or assigns, any firm or corporation, its successors or assigns, or any State, political subdivision, or municipality authorized in accordance with the provisions of this subchapter to build a bridge between two or more States, all such rights and powers to enter upon lands and acquire, condemn, occupy, possess, and use real estate and other property in the respective States needed for the location, construction, operation, and maintenance of such bridge and its approaches, as are possessed by railroad corporations for railroad purposes or by bridge corporations for bridge purposes in the State in which such real estate or other property is situated, upon making just compensation therefor to be ascertained and paid according to the laws of such State, and the proceedings therefor shall be the same as in the condemnation or expropriation of property for public purposes in such State."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/532?type=usc&year=mostrecent&link-type=html"},"by":{"1":"2","2":"14, 18","3":"18"},"q":[{"src":"brief","b":2,"text":"ascertained and paid according to the laws of [the] State","cite":"33 U.S.C. 532"},{"src":"brief","b":3,"text":"ascertained and paid according to the laws","cite":"33 U.S.C. § 532"}]},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","by":{"1":"42"}},{"t":"usc","label":"43 U.S.C. § 945a","url":"https://www.law.cornell.edu/uscode/text/43/945a","by":{"1":"24"}},{"t":"law","label":"Act to Amend the Natural Gas Act, Pub. L. No. 80-245","by":{"1":"6"}},{"t":"law","label":"Pub. L. No. 109-58","url":"https://www.govinfo.gov/link/plaw/109/public/58","by":{"1":"25","2":"30"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"2":"31"}},{"t":"case","label":"(III) Cases—Continued: Alyeska Pipeline Serv. Co. v. Wilderness Soc’y","cite":"421 U.S. 240","y":1975,"id":"1974/73-1977","sc":1,"by":{"2":"29"}},{"t":"case","label":"Burks v. Lasker","cite":"441 U.S. 471","y":1979,"id":"1978/77-1724","sc":1,"by":{"2":"25","3":"4"}},{"t":"case","label":"Dolan v. City of Tigard","cite":"512 U.S. 374","y":1994,"id":"1993/93-518","sc":1,"by":{"2":"13"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"by":{"2":"26","3":"4"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"2":"27, 28"},"q":[{"src":"brief","b":2,"text":"judicial consensus so broad and unquestioned that we must presume Congress knew of and endorsed it.","cite":"543 U.S. 335, 349"}]},{"t":"case","label":"Johnson v. Transportation Agency","cite":"480 U.S. 616","y":1987,"id":"1986/85-1129","sc":1,"by":{"2":"31"}},{"t":"case","label":"Lackey v. Stinnie","cite":"604 U.S. 192","y":2025,"id":"2024/23-621","sc":1,"by":{"2":"29"}},{"t":"case","label":"Pung v. Isabella County","cite":"146 S. Ct. 1964","y":2026,"id":"2025/25-95","sc":1,"by":{"2":"12"}},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"are defined by existing rules or understandings that stem from an independent source such as state law.","cite":"467 U.S. 986, 1001"}]},{"t":"case","label":"United States v. 50 Acres of Land","cite":"469 U.S. 24","y":1984,"id":"1984/83-1170","sc":1,"by":{"2":"12"},"q":[{"src":"brief","b":2,"text":"just compensation normally is to be measured by ‘the market value of the property at the time of the taking.’","cite":"469 U.S. 24, 29"}]},{"t":"case","label":"United States v. Reynolds","cite":"397 U.S. 14","y":1970,"id":"1969/88","sc":1,"by":{"2":"21"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"2":"13"}},{"t":"law","label":"Equal Access to Justice Act, Pub. L. No. 96-481","url":"https://www.govinfo.gov/link/statute/94/2325","by":{"2":"13"}},{"t":"usc","label":"16 U.S.C. § 791a","url":"https://www.law.cornell.edu/uscode/text/16/791a","by":{"2":"5"}},{"t":"usc","label":"33 U.S.C. § 525","url":"https://www.law.cornell.edu/uscode/text/33/525","by":{"2":"14"}},{"t":"usc","label":"15 U.S.C. § 717","url":"https://www.law.cornell.edu/uscode/text/15/717","subs":["(a)","(b)"],"stext":{"head":"§717. Regulation of natural gas companies","paras":[[0,"(a) Necessity of regulation in public interest"],[0,"As disclosed in reports of the Federal Trade Commission made pursuant to S. Res. 83 (Seventieth Congress, first session) and other reports made pursuant to the authority of Congress, it is declared that the business of transporting and selling natural gas for ultimate distribution to the public is affected with a public interest, and that Federal regulation in matters relating to the transportation of natural gas and the sale thereof in interstate and foreign commerce is necessary in the public interest."],[0,"(b) Transactions to which provisions of chapter applicable"],[0,"The provisions of this chapter shall apply to the transportation of natural gas in interstate commerce, to the sale in interstate commerce of natural gas for resale for ultimate public consumption for domestic, commercial, industrial, or any other use, and to natural-gas companies engaged in such transportation or sale, and to the importation or exportation of natural gas in foreign commerce and to persons engaged in such importation or exportation, but shall not apply to any other transportation or sale of natural gas or to the local distribution of natural gas or to the facilities used for such distribution or to the production or gathering of natural gas."],[0,"(c) Intrastate transactions exempt from provisions of chapter; certification from State commission as conclusive evidence"],[0,"The provisions of this chapter shall not apply to any person engaged in or legally authorized to engage in the transportation in interstate commerce or the sale in interstate commerce for resale, of natural gas received by such person from another person within or at the boundary of a State if all the natural gas so received is ultimately consumed within such State, or to any facilities used by such person for such transportation or sale, provided that the rates and service of such person and facilities be subject to regulation by a State commission. The matters exempted from the provisions of this chapter by this subsection are declared to be matters primarily of local concern and subject to regulation by the several States. A certification from such State commission to the Federal Power Commission that such State commission has regulatory jurisdiction over rates and service of such person and facilities and is exercising such jurisdiction shall constitute conclusive evidence of such regulatory power or jurisdiction."],[0,"(d) Vehicular natural gas jurisdiction"],[0,"The provisions of this chapter shall not apply to any person solely by reason of, or with respect to, any sale or transportation of vehicular natural gas if such person is—"],[1,"(1) not otherwise a natural-gas company; or"],[1,"(2) subject primarily to regulation by a State commission, whether or not such State commission has, or is exercising, jurisdiction over the sale, sale for resale, or transportation of vehicular natural gas."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/717?type=usc&year=mostrecent&link-type=html"},"by":{"2":"1, 4, 33, 4"},"q":[{"src":"brief","b":2,"text":"the transportation of natural gas in interstate commerce.","cite":"15 U.S.C. 717(b)"},{"src":"brief","b":2,"text":"[f ]ederal regulation in matters relating to the transportation of natural gas and the sale thereof in interstate and foreign commerce is necessary in the public interest.","cite":"15 U.S.C. 717(a)"}]},{"t":"usc","label":"42 U.S.C. § 4654","url":"https://www.law.cornell.edu/uscode/text/42/4654","subs":["(a)","(a)(1)","(a)(2)"],"by":{"2":"29, 13, 13"},"q":[{"src":"brief","b":2,"text":"cannot acquire the real property by condemnation.","cite":"42 U.S.C. 4654(a)(1)"}]},{"t":"reg","label":"Exec. Order No. 14,154, Unleashing American Energy, 90 Fed. Reg. 8353","url":"https://www.govinfo.gov/link/fr/90/8353","by":{"2":"33"}},{"t":"reg","label":"Exec. Order No. 14,156, Declaring a National Energy Emergency, 90 Fed. Reg. 8433","url":"https://www.govinfo.gov/link/fr/90/8433","by":{"2":"33"}},{"t":"reg","label":"82 Fed. Reg. 60,007","url":"https://www.govinfo.gov/link/fr/82/60007","by":{"2":"6"}},{"t":"case","label":"Bank of Am. Nat. Tr. & Sav. Ass’n v. Parnell","cite":"352 U.S. 29","y":1956,"id":"1956/21","sc":1,"by":{"3":"10"}},{"t":"case","label":"Chevron Oil Co. v. Huson","cite":"404 U.S. 97","y":1971,"id":"1971/70-11","sc":1,"by":{"3":"3"}},{"t":"case","label":"Clearfield Tr. Co. v. United States","cite":"318 U.S. 363","y":1943,"id":"scdb/1942-110","sc":1,"by":{"3":"10"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"But the cases this Court cites in 93.97 are cases where the United States is taking land, and then it cites Clearfield Trust, where the Court said that the federal law merchant controls questions about federal commercial paper, and Parnell for --"},{"src":"argument","who":"Justice Jackson","text":"It cites Clearfield Trust, where the Court says that the federal law merchant controls questions of federal commercial paper where the United States is a party, and then it cites Parnell, about 10 years later, where this Court says: Well, when the United States isn't a party, then the federal law merchant doesn't oust state law."}]},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"3":"22"}},{"t":"case","label":"Geier v. Am. Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"by":{"3":"15"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"by":{"3":"18"}},{"t":"case","label":"Hencely v. Fluor Corp.","cite":"146 S. Ct. 1086","y":2026,"id":"2025/24-924","sc":1,"by":{"3":"6"},"q":[{"src":"argument","who":"Justice Thomas","text":"McNAMARA: I think our approach is exactly the approach this Court took last term in Hencely, Your Honor, which is that even-handed state laws --"},{"src":"argument","who":"Chief Justice Roberts","text":"The -- the same could be said of Hencely last term, Your Honor. If the United States puts itself in charge of base security in war zones, no one thinks that you can use state law to sue the United States for its on-base security."},{"src":"argument","who":"Justice Kavanaugh","text":"Well, you've mentioned Hencely a couple times. MR. McNAMARA: Yes, Your Honor."}]},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich, L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"by":{"3":"17"}},{"t":"case","label":"Lindh v. Murphy","cite":"521 U.S. 320","y":1997,"id":"1996/96-6298","sc":1,"by":{"3":"18"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"by":{"3":"4"}},{"t":"case","label":"N.Y. Cent. R.R. Co. v. Winfield","cite":"244 U.S. 147","y":1917,"id":"scdb/1916-068","sc":1,"by":{"3":"5"}},{"t":"case","label":"North Dakota v. United States","cite":"495 U.S. 423","y":1990,"id":"1989/88-926","sc":1,"by":{"3":"2, 3, 6, 9, 15"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","by":{"3":"12"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"3":"4, 5"}}]};